begin;
create or replace function public.is_published_quiz_version(p_quiz_id uuid,p_version_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.publications p where p.quiz_id=p_quiz_id and p.quiz_version_id=p_version_id and p.status='published'); $$;
create policy "published quiz identity readable" on public.quizzes for select using (exists(select 1 from public.publications p where p.quiz_id=quizzes.id and p.status='published'));
create policy "published quiz version readable" on public.quiz_versions for select using (public.is_published_quiz_version(quiz_id,id));
create policy "published quiz items readable" on public.quiz_version_items for select using (exists(select 1 from public.quiz_versions qv where qv.id=quiz_version_items.quiz_version_id and public.is_published_quiz_version(qv.quiz_id,qv.id)));
create policy "published question identity readable" on public.questions for select using (exists(select 1 from public.quiz_version_items qvi join public.quiz_versions qv on qv.id=qvi.quiz_version_id where qvi.question_id=questions.id and public.is_published_quiz_version(qv.quiz_id,qv.id)));
create policy "published question version readable" on public.question_versions for select using (exists(select 1 from public.quiz_version_items qvi join public.quiz_versions qv on qv.id=qvi.quiz_version_id where qvi.question_version_id=question_versions.id and public.is_published_quiz_version(qv.quiz_id,qv.id)));
create policy "published answer options readable" on public.answer_options for select using (exists(select 1 from public.question_versions qver join public.quiz_version_items qvi on qvi.question_version_id=qver.id join public.quiz_versions quizv on quizv.id=qvi.quiz_version_id where answer_options.question_id=qver.question_id and public.is_published_quiz_version(quizv.quiz_id,quizv.id)));
create policy "published answer option versions readable" on public.answer_option_versions for select using (exists(select 1 from public.quiz_version_items qvi join public.quiz_versions quizv on quizv.id=qvi.quiz_version_id where qvi.question_version_id=answer_option_versions.question_version_id and public.is_published_quiz_version(quizv.quiz_id,quizv.id)));
commit;
